import XCTest
import Foundation
@testable import LocalStorageManagement
actor Library:LocalPhotoLibrary {
 var snapshots:[String:LocalSnapshot],presence:[String:LocalPresence],permission:CleanupPermission = .authorized,calls=0
 var fail:CleanupFailure?,partial=false
 init(_ cs:[CleanupCandidate]){snapshots=Dictionary(uniqueKeysWithValues:cs.map{($0.backedUp.localID,$0.backedUp)});presence=Dictionary(uniqueKeysWithValues:cs.map{($0.backedUp.localID,.present)})}
 func read(_ ids:[String]) async throws->LibraryRead{LibraryRead(permission:permission,snapshots:snapshots,presence:presence)}
 func requestDeletion(_ candidates:[CleanupCandidate],context:CleanupContext) async throws{calls+=1;if let fail{throw fail};for c in partial ? Array(candidates.prefix(1)):candidates{snapshots[c.backedUp.localID]=nil;presence[c.backedUp.localID] = .absentConfirmed};if partial{throw CleanupFailure.systemFailed}}
 func setFailure(_ f:CleanupFailure?){fail=f};func setPartial(){partial=true};func access(_ p:CleanupPermission){permission=p}
 func edit(_ c:CleanupCandidate){snapshots[c.backedUp.localID]?.modification=Date()}
 func vanish(_ c:CleanupCandidate){snapshots[c.backedUp.localID]=nil;presence[c.backedUp.localID] = .absentConfirmed}
 func reappear(_ c:CleanupCandidate){snapshots[c.backedUp.localID]=c.backedUp;presence[c.backedUp.localID] = .present}
}
actor Server:CleanupServer {
 let cs:[CleanupCandidate];var expired=false,wrong=false,outage=false,owned=true,consumes=0,prepared=0
 var onConsume:(@Sendable() async->Void)?
 init(_ cs:[CleanupCandidate]){self.cs=cs}
 func prepare(context:CleanupContext,assetIDs:[UUID]) async throws->CleanupProof{if outage{throw CleanupFailure.proof};prepared+=1;return CleanupProof(token:String(repeating:"x",count:43),userId:wrong ? UUID():context.userID,deviceId:context.deviceID,libraryId:context.libraryID,expiresAt:Date().addingTimeInterval(expired ? -1:60),resources:cs.flatMap(\.resources))}
 func consume(_ p:CleanupProof) async throws->CleanupReceipt{consumes+=1;if let onConsume{await onConsume()};if outage || !owned{throw CleanupFailure.proof};return CleanupReceipt(proofId:p.proofId,userId:p.userId,deviceId:p.deviceId,libraryId:p.libraryId,assetIds:p.resources.map(\.assetID),expiresAt:Date().addingTimeInterval(15))}
 func protectionStillOwned(context:CleanupContext,assetIDs:[UUID]) async throws->Bool{if outage{throw CleanupFailure.proof};return owned}
 func report(proofID:UUID,result:String) async{}
 func stale(){expired=true};func mismatch(){wrong=true};func fail(){outage=true};func loseOwnership(){owned=false}
 func hook(_ f:@escaping @Sendable() async->Void){onConsume=f}
}
@MainActor final class WorkflowTests:XCTestCase {
 var directory:URL!
 override func setUpWithError()throws{directory=FileManager.default.temporaryDirectory.appendingPathComponent("cleanup-mocks-"+UUID().uuidString);try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true)}
 override func tearDownWithError()throws{try? FileManager.default.removeItem(at:directory)}
 func fixture(_ cs:[CleanupCandidate]?=nil)throws->(LocalCleanupCoordinator,LocalCleanupStore,Library,Server,[CleanupCandidate]){let cs=cs ?? [candidate()],store=try LocalCleanupStore(url:directory.appendingPathComponent(UUID().uuidString+".sqlite")),lib=Library(cs),server=Server(cs),gate=CleanupGate(developmentBuild:true,explicitFlag:true,disposableContext:true,serverEnabled:true);return(LocalCleanupCoordinator(context:context,gate:gate,store:store,library:lib,server:server),store,lib,server,cs)}
 func reject(_ f:() async throws->Void) async{do{try await f();XCTFail("Unsafe action accepted")}catch{}}
 func testReviewDoesNotDelete() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);let calls=await l.calls;XCTAssertEqual(calls,0);XCTAssertEqual(c.job?.state,.awaitingConfirmation)}
 func testExplicitConfirmationRequired() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await reject{try await c.confirm(explicit:false)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testSuccessfulMockRemovalPreservesProtectedEvidence() async throws{let(c,store,_,_,items)=try fixture();try await c.review(items);try await c.confirm(explicit:true);XCTAssertEqual(c.job?.state,.removed);XCTAssertEqual(c.job?.candidates.first?.resources.first?.status,"PROTECTED");let h=try await store.history(account:context.userID);XCTAssertEqual(h[0].removedCount,1);XCTAssertEqual(h[0].knownBytes,5)}
 func testSystemCancellationNeverMarksDeleted() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await l.setFailure(.systemCancelled);await reject{try await c.confirm(explicit:true)};XCTAssertEqual(c.job?.state,.cancelled);XCTAssertEqual(c.job?.removed.count,0)}
 func testFailedSystemRequestRequiresReconciliation() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await l.setFailure(.systemFailed);await reject{try await c.confirm(explicit:true)};XCTAssertEqual(c.job?.state,.reconcileRequired)}
 func testExpiredProofRejected() async throws{let(c,_,l,s,items)=try fixture();await s.stale();await reject{try await c.review(items)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testMismatchedServerScopeRejected() async throws{let(c,_,l,s,items)=try fixture();await s.mismatch();await reject{try await c.review(items)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testSignOutInvalidatesWorkflow() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await c.invalidateAccount();await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testAccountSwitchCannotReuseWorkflow() async throws{let(c,store,l,s,items)=try fixture();try await c.review(items);await c.invalidateAccount();let other=LocalCleanupCoordinator(context:CleanupContext(userID:UUID(),deviceID:UUID(),libraryID:UUID()),gate:CleanupGate(developmentBuild:true,explicitFlag:true,disposableContext:true,serverEnabled:true),store:store,library:l,server:s);await reject{try await other.review(items)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testForegroundOnly() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await c.background();await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testBackgroundRequiresNewReview() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await c.background();c.resumeForeground();await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testChangedPermissionMidFlowBlocks() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await l.access(.limited);await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testSourceEditBeforeConfirmationBlocks() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await l.edit(items[0]);await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testSourceDisappearsBeforeDeletionBlocks() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);await l.vanish(items[0]);await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testServerOutageAfterReviewBlocks() async throws{let(c,_,l,s,items)=try fixture();try await c.review(items);await s.fail();await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testOwnershipLossAfterReviewBlocks() async throws{let(c,_,l,s,items)=try fixture();try await c.review(items);await s.loseOwnership();await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testProofReplayDoesNotDeleteAgain() async throws{let(c,_,l,_,items)=try fixture();try await c.review(items);try await c.confirm(explicit:true);await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,1)}
 func testIneligibleSelectionRejected() async throws{var i=candidate();i.excluded=true;let(c,_,l,_,items)=try fixture([i]);await reject{try await c.review(items)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testBatchBoundaryAtTen() async throws{let(c,_,l,_,items)=try fixture((0..<11).map{_ in candidate()});await reject{try await c.review(items)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testTenItemBatchWorks() async throws{let(c,_,l,_,items)=try fixture((0..<10).map{_ in candidate()});try await c.review(items);try await c.confirm(explicit:true);let calls=await l.calls;XCTAssertEqual(calls,1);XCTAssertEqual(c.job?.removed.count,10)}
 func testCrashBeforeDeleteCancelsReview() async throws{let(c,store,_,_,items)=try fixture();try await c.review(items);try await c.reconcileStartup();let j=try await store.jobs(account:context.userID);XCTAssertEqual(j[0].state,.cancelled)}
 func testCrashAfterDeleteReconcilesNoRetry() async throws{let(c,store,l,_,items)=try fixture();var j=CleanupJob(context:context,candidates:items);j.state = .systemPending;try await store.save(j);await l.vanish(items[0]);try await c.reconcileStartup();let js=try await store.jobs(account:context.userID),calls=await l.calls;XCTAssertEqual(js[0].state,.removed);XCTAssertEqual(calls,0)}
 func testCrashAfterIntentBeforeRequestDoesNotRetry() async throws{let(c,store,l,_,items)=try fixture();var j=CleanupJob(context:context,candidates:items);j.state = .deletionRequested;try await store.save(j);try await c.reconcileStartup();let js=try await store.jobs(account:context.userID),calls=await l.calls;XCTAssertEqual(js[0].state,.reconcileRequired);XCTAssertEqual(calls,0)}
 func testPartialBatchFailureReconcilesNoAutomaticDeletion() async throws{let(c,store,l,_,items)=try fixture((0..<2).map{_ in candidate()});try await c.review(items);await l.setPartial();await reject{try await c.confirm(explicit:true)};try await c.reconcileStartup();let js=try await store.jobs(account:context.userID),calls=await l.calls;XCTAssertEqual(js[0].removed.count,1);XCTAssertEqual(js[0].state,.reconcileRequired);XCTAssertEqual(calls,1)}
 func testStaleDeletedRecordWithPresentAssetReconciles() async throws{let(c,store,l,_,items)=try fixture();try await c.review(items);try await c.confirm(explicit:true);await l.reappear(items[0]);try await c.reconcileStartup();let js=try await store.jobs(account:context.userID);XCTAssertEqual(js[0].removed.count,0);XCTAssertEqual(js[0].state,.reconcileRequired)}
 func testLimitedAccessCannotInferRemoval() async throws{let(c,store,l,_,items)=try fixture();var j=CleanupJob(context:context,candidates:items);j.state = .systemPending;try await store.save(j);await l.vanish(items[0]);await l.access(.limited);try await c.reconcileStartup();let js=try await store.jobs(account:context.userID);XCTAssertEqual(js[0].state,.reconcileRequired);XCTAssertEqual(js[0].removed.count,0)}
 func testNoLongLivedProofInJournal() async throws{let(c,store,_,_,items)=try fixture();try await c.review(items);let encoded=try JSONEncoder().encode(await store.jobs(account:context.userID));let text=String(decoding:encoded,as:UTF8.self);XCTAssertFalse(text.contains(String(repeating:"x",count:43)));XCTAssertFalse(text.contains("token"));XCTAssertFalse(text.contains("X-Amz"))}
 func testCleanupHistoryOnlySafeAggregates() async throws{let(c,store,_,_,items)=try fixture();try await c.review(items);try await c.confirm(explicit:true);let h=try await store.history(account:context.userID);XCTAssertEqual(h.count,1);XCTAssertEqual(h[0].removedCount,1);XCTAssertEqual(h[0].unknownSizes,0)}
 func testLogoutWhileConsumingProofPreventsDeletion() async throws{let(c,_,l,s,items)=try fixture();try await c.review(items);await s.hook{await c.invalidateAccount()};await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testSourceEditedDuringServerConsumePreventsDeletion() async throws{let(c,_,l,s,items)=try fixture();try await c.review(items);await s.hook{await l.edit(items[0])};await reject{try await c.confirm(explicit:true)};let calls=await l.calls;XCTAssertEqual(calls,0)}
 func testPendingJobBeyondFirstPageBlocksNewReview() async throws{let(c,store,l,s,items)=try fixture();for _ in 0..<105{var j=CleanupJob(context:context,candidates:[candidate()]);j.state = .cancelled;try await store.save(j)};var pending=CleanupJob(context:context,candidates:items);pending.state = .systemPending;try await store.save(pending);await reject{try await c.review(items)};let calls=await l.calls,prepared=await s.prepared;XCTAssertEqual(calls,0);XCTAssertEqual(prepared,0)}
 func testLostPlannerCommitReconcilesWithoutSecondDeletion() async throws{let(_,store,l,s,items)=try fixture(),marker=FailOnceMarker();let c=LocalCleanupCoordinator(context:context,gate:CleanupGate(developmentBuild:true,explicitFlag:true,disposableContext:true,serverEnabled:true),store:store,library:l,server:s,recordRemoval:{_ in try await marker.record()});try await c.review(items);await reject{try await c.confirm(explicit:true)};try await c.reconcileStartup();let jobs=try await store.jobs(account:context.userID),calls=await l.calls,attempts=await marker.attempts;XCTAssertEqual(jobs[0].state,.removed);XCTAssertEqual(calls,1);XCTAssertEqual(attempts,2)}
}

actor FailOnceMarker{var attempts=0;func record()throws{attempts+=1;if attempts==1{throw CleanupFailure.storage}}}
